#!/bin/bash
# 场景图 v2：按开发项目评估（CG制作/场景图与主城评估_1102.md）修改，Rhett 11-02 11:28「遵循汇报安排工作」批准
cd /workspace/work/.agents/skills/credit-media-skill
export CREDIT_MEDIA_API_KEY=proxy
O=/workspace/projects/04b4b2af-0042-4c1b-a4f3-cdc315529fa5/promo/scenes_v2; V1=$O/../scenes_v1; KV=$O/../keyvisual_v1
PRE="写实电影级场景主视觉，16:9宽银幕横构图，与参考图同一质感「暗岩传说」，体积光、浮尘、湿润反光石面，无人物或只有极小的人物剪影提供尺度。"
DLC="地底之海世界观：头顶是岩石穹顶，没有天空；青绿冷调阴影与熔铜暖金灯光对比。"
BASE="保留本区域自己的主色调，欧式暗黑奇幻，质感与暗调和参考图一致。"
INV="重要：镜渊城是倒挂在穹顶上的城市，塔尖朝下指向海面，不是立在地面上的城市。"
NEG="画面中不要出现任何文字、字幕、水印、UI；不要卡通。"
gen(){ n=$1; tone=$2; p=$3; shift 3; a=(); for i in "$@"; do a+=(--image "$i"); done
  bash scripts/run.sh image --model gpt-image-2 --size 1536x1024 --quality high --prompt "$PRE $tone $p $NEG" "${a[@]}" --out $O/$n.png > $O/$n.log 2>&1 & }
gen H1_bellharbor_v2 "$DLC $INV" "鸣钟港全景，俯视3/4视角：地底之海中央一座高出水面的黑色玄武岩礁台港口，建筑由倒扣的沉船船壳、带铜绿的碎钟壳和巨鲸肋骨搭成的拾荒港，木栈桥与铁锚、暖黄船灯成串；台地中央圆形广场立着木架悬挂的青铜公告钟与发光传送阵；左侧铸钟坊烟囱冒橙色熔光，右侧码头停三艘渡船，后方高处东西两座小塔（东塔冷青钟亭、西塔暗红灯火）；正上方穹顶倒挂着镜渊城，其灯火倒映在港内水面；能看清各区块轮廓。不要完整的哥特街区，不要尖顶大教堂。" $KV/S2_coast.png
gen H2_forge_v2 "$DLC" "在参考图基础上修改，保留整体构图与熔光：画面中央改为一座带发光符文圈的铸造砧台（铸造台）；左后方墙面加一道向下的铜梯拱门，门楣挂小钟，门内透出更深处的炉火；右侧高窗外可见倒挂城市的冷青灯点；墙上武器减少一半。" $V1/H2_forge.png
gen S1_mirrordeep_v2 "$DLC $INV" "镜渊城：穹顶向下倒挂的哥特钟楼城，塔尖朝下，倒挂的铜钟悬在塔尖；下方是镜面般静止的黑水与碎石平台，平台间有发光石板步道，三座立在水面上的巨大石质镜框，镜面映出另一处景象；中央小广场摆着一口倒扣的大钟（倒钟广场），旁边小营地篝火。" $KV/S2_coast.png
gen S3_belltower_v2 "$DLC" "无声钟楼：地底之海中央拔起的铜石混筑钟楼，塔身五段收分，顶层开放钟室悬一口暗红与冷青交织的巨钟；塔门是两根立柱的门架挂着一口裂开的铜钟；塔脚是小营地与篝火，西侧一道铜梯通向冒熔光的地下口；海面散落坠落的安魂钟和三根挂钟的石锚柱；穹顶岩壁垂下铁链。没有天空，没有雪山。" $KV/S2_coast.png
gen S4_abyss_v2 "" "暗岩深渊：巨大竖井式深渊，一层层圆形石台向下螺旋，上段沙金、中段冰蓝、下段熔红色调；最底层平整的圆形战斗石台上悬浮暗岩之魂（黑紫晶簇构成的人形，布满熔红裂纹）；台边有2到3道发光石门岔路。" $KV/S4_abyss.png
gen D1_bronze_furnace "$DLC" "钟铜熔炉·浇铸台：无声钟楼地下的铸钟熔炉，直径约25米的平整圆形浇铸战斗台中央是半铸成的巨钟钟模，熔铜从高处槽口浇下沿地面沟槽流淌，四周站着未完成的铜铸傀儡；橙金熔光为主，边缘冷青钟铜反光。" $V1/D1_tower_foundry.png
wait
gen D2_choice_bell "$DLC" "钟楼顶层·抉择之钟：一口比教堂还大的巨钟悬在断裂的穹顶下，周围铁链垂向深渊，下方远处是翻涌的黑色潮水；钟体左半泛冷青光、右半透暗红熔光，两色在钟腰交界；钟下是一圈平整的圆形石台，地面刻着发红光的抉择印记。" $V1/D2_bellmother.png
gen D3_domain_A_v2 "$DLC $INV" "钟楼领地（结局A）：倒挂在穹顶的镜渊城灯火一盏盏重新亮起；下方镜面海的平台上新建的铜顶建筑可辨：中央三级尖顶钟楼挂旗、冒火光的铁匠工坊、堆满书卷的学会、停船的码头、小圣堂、长街摊位、训练木桩场、档案馆；街上有半透明青色的回响居民身影；钟楼钟里有一个少女轮廓的柔光；金色光束从穹顶裂缝洒下。" $KV/S2_coast.png
gen D4_tidewhale_v2 "$DLC" "沉钟海岸深潮口：涨潮的黑色海面，一头远古巨鲸从水下破出，背上藤壶间只嵌着三口大小不一的古铜钟；钟声激起金色环形浪纹，圈出约30米的战斗水域；远景是侧卧在浅滩的巨钟、六棱玄武岩柱群和东岸灯塔射出的光束，穹顶岩壁与雷云。不要城市。" $V1/D4_tidewhale.png
gen D5_mirrorknights_v2 "$DLC $INV" "镜渊城回响长街：积水的石板街道倒影清晰；一队步行骑士列阵，没有马，盔甲由大小不一的碎镜片拼成，裂缝透冷青光，每片镜子映出不同角度；中央团长瑟兰更高大，手持镜面大盾和长剑，披破旗；倒影里的骑士动作慢半拍；两侧是倒挂的街屋，头顶倒挂铜钟。" $KV/S2_coast.png
gen B1_greystone_v2 "$BASE" "灰石营地：灰色山岩环抱的边境营地，原木尖桩围栏与石墙，欧式木构瞭望塔挂旗（不要东方飞檐）；营地中心偏西一口石砌古井，直径约3米，带木制辘轳架，井架上挂一口小铜钟；中央篝火；北侧圆形石砌传送阵发蓝光；南侧一道石拱门通向绿色原野，东北山路上坡，西南木栈道伸进雾沼，东边一片暗林；黄昏炊烟。" $V1/B1_greystone.png
gen B4_greenwind_v2 "$BASE" "翠风原野：辽阔绿色丘陵，风吹麦浪；近景一条蜿蜒小河与石拱桥，中景麦穗村4到5栋木石农舍和一座高大风车塔，远处小山坡上一圈倒伏石柱围着发光祭坛（星落遗迹）；晴空大云影。" $V1/B4_greenwind.png
gen B7_emberwaste_v2 "$BASE" "烬落荒原：灰烬焦土荒原，地缝熔岩流成网；左远景一座高烟囱林立、仍在运转的铸造厂，冒黑烟和橙色炉口；正中远景火山口被凿成巨大王座形石门，门内熔光（熔心王座），不是城堡；近景右侧一角是石墙与旗帜的据点；余烬飞舞，暗红天光。" $V1/B7_emberwaste.png
wait
